"""Reference solution for C1 (next_cron_times). Not shown to the models."""
import datetime as _dt

_FIELDS = [("minute", 0, 59), ("hour", 0, 23), ("dom", 1, 31), ("month", 1, 12), ("dow", 0, 7)]


def _int(text):
    if not text.isdigit():
        raise ValueError(f"not an integer: {text!r}")
    return int(text)


def _parse_field(text, lo, hi, star_hi):
    values = set()
    if text == "":
        raise ValueError("empty field")
    for item in text.split(","):
        if item == "":
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            base, _, step_text = item.partition("/")
            step = _int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
            if base != "*" and "-" not in base:
                raise ValueError("step needs * or a range")
        else:
            base = item
        if base == "*":
            a, b = lo, star_hi
        elif "-" in base:
            a_text, _, b_text = base.partition("-")
            a, b = _int(a_text), _int(b_text)
            if a > b:
                raise ValueError("range start > end")
        else:
            a = b = _int(base)
        if a < lo or b > hi:
            raise ValueError("value out of range")
        values.update(range(a, b + 1, step))
    return values


def _parse(expr):
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("need 5 fields")
    sets = []
    for text, (_, lo, hi) in zip(parts, _FIELDS):
        star_hi = 6 if hi == 7 else hi
        sets.append(_parse_field(text, lo, hi, star_hi))
    minute, hour, dom, month, dow = sets
    if 7 in dow:
        dow = (dow - {7}) | {0}
    return minute, hour, dom, month, dow, parts[2] == "*", parts[4] == "*"


def next_cron_times(expr, start, n):
    minute, hour, dom, month, dow, dom_star, dow_star = _parse(expr)
    minutes = sorted(minute)
    hours = sorted(hour)

    def day_ok(d):
        if d.month not in month:
            return False
        dom_hit = d.day in dom
        dow_hit = (d.weekday() + 1) % 7 in dow
        if dom_star and dow_star:
            return True
        if dom_star:
            return dow_hit
        if dow_star:
            return dom_hit
        return dom_hit or dow_hit

    out = []
    limit = start + _dt.timedelta(days=3000)
    day = start.date()
    while len(out) < n:
        if _dt.datetime.combine(day, _dt.time()) > limit:
            raise ValueError("not enough matches within 3000 days")
        if day_ok(day):
            for h in hours:
                for m in minutes:
                    t = _dt.datetime(day.year, day.month, day.day, h, m)
                    if t > start and t <= limit:
                        out.append(t)
                        if len(out) == n:
                            return out
        day += _dt.timedelta(days=1)
    return out

"""Reference solution for C3 (evaluate). Not shown to the models."""


def _tokens(s):
    out, i = [], 0
    while i < len(s):
        c = s[i]
        if c in " \t\r\n":
            i += 1
        elif c.isdigit() and c in "0123456789":
            j = i
            while j < len(s) and s[j] in "0123456789":
                j += 1
            out.append(("num", int(s[i:j]))); i = j
        elif s.startswith("**", i):
            out.append(("op", "**")); i += 2
        elif c in "+-*/%()":
            out.append(("op", c)); i += 1
        else:
            raise ValueError(f"bad character {c!r}")
    return out


def _tdiv(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def evaluate(expr):
    toks = _tokens(expr)
    pos = 0

    def peek():
        return toks[pos][1] if pos < len(toks) and toks[pos][0] == "op" else None

    def take():
        nonlocal pos
        pos += 1
        return toks[pos - 1]

    def expr_():
        v = term()
        while peek() in ("+", "-"):
            op = take()[1]
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/", "%"):
            op = take()[1]
            r = unary()
            if op == "*":
                v = v * r
            elif op == "/":
                v = _tdiv(v, r)
            else:
                v = v - r * _tdiv(v, r)
        return v

    def unary():
        if peek() in ("+", "-"):
            op = take()[1]
            v = unary()
            return -v if op == "-" else v
        return power()

    def power():
        base = atom()
        if peek() == "**":
            take()
            e = unary()
            if e < 0:
                raise ValueError("negative exponent")
            return base ** e
        return base

    def atom():
        if pos >= len(toks):
            raise ValueError("unexpected end")
        kind, val = take()
        if kind == "num":
            return val
        if val == "(":
            v = expr_()
            if peek() != ")":
                raise ValueError("missing )")
            take()
            return v
        raise ValueError(f"unexpected {val!r}")

    if not toks:
        raise ValueError("empty")
    v = expr_()
    if pos != len(toks):
        raise ValueError("trailing tokens")
    return v

"""Reference solution for C2 (shell_split). Not shown to the models."""


def shell_split(s):
    words, cur, have = [], [], False
    i, n = 0, len(s)
    ws = " \t\r\n"
    while i < n:
        c = s[i]
        if c in ws:
            if have:
                words.append("".join(cur))
                cur, have = [], False
            i += 1
        elif c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            cur.append(s[i + 1]); have = True; i += 2
        elif c == "'":
            j = s.find("'", i + 1)
            if j < 0:
                raise ValueError("unterminated single quote")
            cur.append(s[i + 1:j]); have = True; i = j + 1
        elif c == '"':
            i += 1; have = True
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                c = s[i]
                if c == '"':
                    i += 1; break
                if c == "\\" and i + 1 < n and s[i + 1] in '"\\':
                    cur.append(s[i + 1]); i += 2
                else:
                    cur.append(c); i += 1
        else:
            cur.append(c); have = True; i += 1
    if have:
        words.append("".join(cur))
    return words
